from h34 import *
M=mcq;F=tf;S=short;N=num
numberline('c4-maths-eg-frog.svg',0,24,3,[(i,i+3,'+3') for i in range(0,24,3)],'The frog jumps 3 steps at a time: multiples of 3')
b='<rect width="720" height="220" fill="#fffaf0"/>'
for r in range(4):
    for c in range(6): b+=f'<circle cx="{70+c*50}" cy="{50+r*40}" r="15" fill="#e4572e"/>'
b+='<text x="400" y="100" font-size="20" font-weight="bold">4 rows of 6 = 4 × 6 = 24</text><text x="400" y="135" font-size="16">6 columns of 4 = 6 × 4 = 24</text><text x="400" y="170" font-size="14">An array shows equal groups in rows and columns</text>'
svgfile('c4-maths-eg-array.svg',720,220,b)
chapter(4,'maths','equal-groups','Equal Groups',
 ('Animal jumps','A frog, a squirrel, a rabbit and a kangaroo are racing to their food. Each animal jumps a different number of steps every time, but each jump is always the same size. The frog jumps 3 steps at a time, so it lands on 3, 6, 9 and 12. Will the frog land on 67? In this chapter you will use equal groups, jumps, arrays and tens to multiply and divide bigger numbers with confidence.'),
 [('Jumping in equal steps',['The frog jumps 3 steps at a time and lands on 3, 6, 9, 12, 15 and 18, and these numbers are called multiples of 3.','Look at the number line on the board, where each jump of 3 starts where the last one ended.','The squirrel jumps 4 steps at a time, so it lands on 4, 8, 12 and 16, which are multiples of 4, and it needs 15 jumps to reach 60.','The rabbit jumps 6 steps at a time and the kangaroo jumps 8, and the smallest 3-digit number the rabbit lands on is 102 after 17 jumps.','The frog cannot land on 67, because 66 is a multiple of 3 and 67 is one more than that.']),
  ('Common multiples',['Some numbers are touched by two animals, and these are called common multiples.','The frog and the squirrel both touch 12, 24 and 36, so these are common multiples of 3 and 4.','The rabbit and the kangaroo both touch 24, 48 and 72, so these are common multiples of 6 and 8.','To reach 48 the rabbit jumps 8 times and the kangaroo jumps 6 times, and to reach 60 the frog jumps 20 times and the rabbit jumps 10 times.','A bigger jump means fewer jumps to reach the same number.']),
  ('The cat and the rat',['If the cat and the rat land on the same number, the cat catches the rat.','The cat starts on 6 and jumps 3 steps each time, while the rat starts on 12 and jumps 2 steps each time.','The cat lands on 9, 12, 15, 18, 21 and 24, and the rat lands on 14, 16, 18, 20, 22 and 24.','Both land on 24 after 6 jumps, so the cat catches the rat at 24.']),
  ('Equal groups and multiplication',['Gulabo’s lily flowers each have 3 petals, so 12 flowers have 12 × 3 petals.','We can break 12 into 10 and 2, so 10 × 3 is 30 petals, 2 × 3 is 6 petals and together that is 36 petals.','In 12 × 3 = 36, the 12 is the number of groups, the 3 is the size of each group, and the 36 is the product.','Multiplication is a quick way to add equal groups again and again.']),
  ('Equal groups and division',['A hibiscus flower has 5 petals and Gulabo counted 80 petals in all, so the number of flowers is 80 ÷ 5.','10 petals make 2 flowers and 50 petals make 10 flowers, so 80 petals make 16 flowers.','Division means finding how many equal groups we can make, or how big each group is.','Multiplication and division undo each other: 16 × 5 = 80 and 80 ÷ 5 = 16.']),
  ('Rows and columns: arrays',['Marigold saplings in a box are planted in rows and columns, and an arrangement like this is called an array.','On the board there are 4 rows of 6 dots, so there are 4 × 6 = 24 dots, and counting by columns gives 6 × 4 = 24 dots as well.','Radha bakes 18 cupcakes in one tray and uses two trays at a time, so she makes 36 cupcakes in one go.','The same number can be arranged in different ways, for example 12 can be 2 rows of 6, 3 rows of 4 or 4 rows of 3.']),
  ('Doubling magic',['Magician Anvi doubles the flowers, so 23 flowers become 46 flowers.','Doubling means multiplying by 2, so the double of 32 is 64, of 14 is 28, of 26 is 52, of 17 is 34, of 39 is 78 and of 45 is 90.','The ones digit of any doubled number is always 0, 2, 4, 6 or 8, so a doubled number is always even.','Halving is the opposite of doubling, and we can use doubling and halving to help with multiplication.']),
  ('Patterns in the multiplication chart',['In the chart we multiply the row number by the column number, so row 7 and column 7 hold the same numbers.','That happens because 3 × 7 is the same as 7 × 3, and the order of multiplication does not change the product.','In row 8 the ones digits are 8, 6, 4, 2, 0 and then they repeat the same way.','In row 5 the ones digits are only 5 and 0, and every product in an even row is an even number.','Spotting patterns like these makes multiplication easier to remember.']),
  ('Multiples of ten and a hundred',['10 tricycles have 10 × 3 = 30 wheels, and 20 tricycles have 20 × 3 = 60 wheels, which is double the 10 tricycles.','30 cars have 30 × 4 = 120 wheels, because 30 × 4 is 3 times 10 × 4.','If we know 6 × 8 = 48, then 60 × 8 = 480, which is ten times as big.','100 bikes with 2 people on each carry 100 × 2 = 200 people.']),
  ('Multiplying using tens',['To find 18 × 4, split 18 into 10 and 8, so 10 × 4 = 40 and 8 × 4 = 32, and the total is 72.','To find 23 × 8, split 23 into 20 and 3, so 20 × 8 = 160 and 3 × 8 = 24, and the total is 184.','A bullock cart needs 8 bamboo rods, so 23 carts need 184 rods.','Splitting a number into tens and ones helps us multiply in our head.']),
  ('Division by taking away groups',['A factory has 58 wheels and each tempo needs 3 wheels, so we find 58 ÷ 3.','We take away 10 tempos, which uses 30 wheels, and 28 wheels are left.','We take away 5 more tempos, which use 15 wheels, so 13 wheels are left.','We take away 3 more tempos, which use 9 wheels, so 4 wheels are left, and then 1 more tempo uses 3 wheels, leaving 1 wheel.','So 10 + 5 + 3 + 1 = 19 tempos can be made and 1 wheel is left over.','In 88 ÷ 4 for cows’ legs, we take away 10 cows twice and then 2 more cows, so there are 22 cows.'])],
 [('Gulabo’s 12 lily flowers each have 3 petals. How many petals are there in all?',[('We need 12 groups of 3 petals, so 12 × 3.','Each flower is a group of 3.'),('Split 12 into 10 and 2.','Tens are easy to multiply.'),('10 × 3 = 30 and 2 × 3 = 6.','Multiply each part by 3.'),('30 + 6 = 36, so there are 36 petals.','Add the two parts.')]),
  ('A bullock cart needs 8 bamboo rods. How many rods are needed for 23 carts?',[('We need 23 groups of 8, so 23 × 8.','Each cart needs a group of 8 rods.'),('Split 23 into 20 and 3.','This makes the sums simpler.'),('20 × 8 = 160 and 3 × 8 = 24.','Multiply each part by 8.'),('160 + 24 = 184, so 184 rods are needed.','Add the two parts.')]),
  ('A factory has 58 wheels and each tempo needs 3 wheels. How many tempos can it make?',[('We find 58 ÷ 3.','Each tempo is a group of 3 wheels.'),('Take away 10 tempos: 58 − 30 = 28 wheels left.','30 wheels are used for 10 tempos.'),('Take away 5 tempos: 28 − 15 = 13, then 3 tempos: 13 − 9 = 4, then 1 tempo: 4 − 3 = 1.','We keep taking away groups of 3.'),('10 + 5 + 3 + 1 = 19 tempos, and 1 wheel is left.','Add the tempos we made.')]),
  ('Find the first number both the cat and the rat land on. The cat starts at 6 and jumps 3, the rat starts at 12 and jumps 2.',[('Cat: 9, 12, 15, 18, 21, 24.','The cat adds 3 each time.'),('Rat: 14, 16, 18, 20, 22, 24.','The rat adds 2 each time.'),('Both land on 18 only at different times, but they are on the same number at the same time at 24 after 6 jumps.','The cat catches the rat when they land together.')])],
 ('Explain what equal groups, multiplication and division mean, and how splitting a number into tens helps.',['Equal groups mean the same number in each group','Multiplication finds the total of equal groups','Division finds how many groups or how many in each group','Splitting into tens and ones makes multiplying easier','Multiplication and division undo each other'],['Thinking a group can have different sizes','Adding the number of groups and group size instead of multiplying','Forgetting to add the two partial products']),
 ['Multiples are the numbers we land on when we jump in equal steps.','A common multiple is a number that is a multiple of two numbers.','Multiplication finds the total of equal groups, and division shares or groups a total equally.','An array shows multiplication in rows and columns.','Splitting a number into tens and ones helps with multiplying and dividing.','Doubling always gives an even number, and multiplying by 10 makes a number ten times bigger.'],
 [M('1',1,'Which of these is a multiple of 3?','12',[('13','13 is one more than 12'),('14','14 is not on the jumps of 3')],'3, 6, 9, 12 are the multiples of 3.'),
  M('2',1,'What is 4 × 6?','24',[('10','10 is 4 plus 6'),('46','That joins the digits instead of multiplying')],'Four groups of 6 make 24.'),
  M('3',1,'The double of 14 is ___.','28',[('16','16 is 14 plus 2'),('24','24 is 14 plus 10')],'Doubling 14 gives 28.'),
  M('4',1,'What is 10 × 3?','30',[('13','13 is 10 plus 3'),('300','300 would be 100 × 3')],'Ten groups of 3 make 30.'),
  M('5',2,'What is 18 × 4?','72',[('64','That is 16 × 4'),('22','22 is 18 plus 4')],'10 × 4 = 40, 8 × 4 = 32, and 40 + 32 = 72.'),
  M('6',2,'Which number do both the frog (3 steps) and squirrel (4 steps) land on?','12',[('13','The frog does not land on 13'),('15','The squirrel does not land on 15')],'12 is a multiple of both 3 and 4.'),
  M('7',2,'In 12 × 3 = 36, what is the number of groups?','12',[('3','3 is the size of each group'),('36','36 is the product')],'12 groups of 3 make 36.'),
  M('8',2,'How many cows have 88 legs in all?','22',[('20','20 cows have 80 legs'),('24','24 cows have 96 legs')],'88 ÷ 4 = 22.'),
  N('9',2,'How many petals are in 12 lily flowers with 3 petals each?',36,'12 × 3 = 36.',[(15,'15 is 12 plus 3')]),
  N('10',3,'58 wheels are used for tempos with 3 wheels each. How many full tempos can be made?',19,'58 ÷ 3 is 19 with 1 wheel left over.',[(20,'20 tempos would need 60 wheels')]),
  F('11',2,'The ones digit of a doubled number can be 3.',False,'Doubling gives an even number, so the ones digit is 0, 2, 4, 6 or 8.'),
  F('12',3,'3 × 7 and 7 × 3 give the same product.',True,'The order does not change a product.')],
 svgs=[('c4-maths-eg-frog','A number line from 0 to 24 with arcs showing jumps of 3.','The frog lands on the multiples of 3.'),('c4-maths-eg-array','An array of 4 rows with 6 dots in each row.','4 rows of 6 make 24, so 4 × 6 = 6 × 4 = 24.')],
 keep=['multiple','array','product'])
